// =======================
// PREPARE OUTDOOR - FULL SNAPSHOT
// =======================

function round1(value) {
    const n = Number(value);
    if (Number.isNaN(n)) return null;
    return Math.round(n * 10) / 10;
}

const topic = msg.topic || "";
const metadata = msg.payload?.metadata || {};
const value = round1(msg.payload?.value);

if (!topic || value === null) {
    return null;
}

const parts = topic.split("/");
const sensor = parts[2];

let state = context.get("weather_state") || {
    temperature: null,
    humidity: null,
    pressure: null,
    windspeed: null,
    visibility: null,
    dewpoint: null,
    original_date: null,
    timestamp: null
};

state.original_date = metadata.original_date || state.original_date;
state.timestamp = metadata.original_date || state.timestamp;

if (sensor === "temperature") {
    state.temperature = value;
}

if (sensor === "humidity") {
    state.humidity = value;
}

if (sensor === "pressure_mm_hg") {
    state.pressure = value + " mmHg";
}

if (sensor === "windspeed") {
    state.windspeed = value;
}

if (sensor === "visibility") {
    state.visibility = value + " km";
}

if (sensor === "dewpoint") {
    state.dewpoint = value + " °C";
}

context.set("weather_state", state);

msg.original_date = state.original_date;
msg.timestamp = state.timestamp;
msg.temperature = state.temperature;
msg.humidity = state.humidity;
msg.pressure = state.pressure;
msg.windspeed = state.windspeed;
msg.visibility = state.visibility;
msg.dewpoint = state.dewpoint;

return msg;

// =======================
// PREPARE INDOOR - FULL SNAPSHOT
// =======================

function round1(value) {
    const n = Number(value);
    if (Number.isNaN(n)) return null;
    return Math.round(n * 10) / 10;
}

const topic = msg.topic || "";
const metadata = msg.payload?.metadata || {};
const value = round1(msg.payload?.value);

if (!topic || value === null) {
    return null;
}

const parts = topic.split("/");
if (parts.length < 4) {
    return null;
}

const room = parts[2];
const metric = parts[3];

const roomMap = {
    kitchen: 1,
    livingroom: 2,
    laundry: 3,
    office: 4,
    bathroom: 5,
    outside_building: 6,
    ironing_room: 7,
    teen_room: 8,
    parents_room: 9
};

const roomNum = roomMap[room];
if (!roomNum) {
    return null;
}

let state = context.get("indoor_state") || {
    T1: null, RH_1: null,
    T2: null, RH_2: null,
    T3: null, RH_3: null,
    T4: null, RH_4: null,
    T5: null, RH_5: null,
    T6: null, RH_6: null,
    T7: null, RH_7: null,
    T8: null, RH_8: null,
    T9: null, RH_9: null,
    original_date: null,
    timestamp: null
};

state.original_date = metadata.original_date || state.original_date;
state.timestamp = metadata.original_date || state.timestamp;

if (metric === "temperature") {
    state["T" + roomNum] = value;
} else if (metric === "humidity") {
    state["RH_" + roomNum] = value;
} else {
    return null;
}

context.set("indoor_state", state);

if (metric === "temperature") {
    const energyIndoor = global.get("indoor_temperature_state") || {
        rooms: {},
        updated_at: null
    };

    energyIndoor.rooms[room] = {
        value,
        timestamp: metadata.original_date || new Date().toISOString()
    };
    energyIndoor.updated_at = metadata.original_date || new Date().toISOString();

    global.set("indoor_temperature_state", energyIndoor);
}

msg.original_date = state.original_date;
msg.timestamp = state.timestamp;

msg.T1 = state.T1;   msg.RH_1 = state.RH_1;
msg.T2 = state.T2;   msg.RH_2 = state.RH_2;
msg.T3 = state.T3;   msg.RH_3 = state.RH_3;
msg.T4 = state.T4;   msg.RH_4 = state.RH_4;
msg.T5 = state.T5;   msg.RH_5 = state.RH_5;
msg.T6 = state.T6;   msg.RH_6 = state.RH_6;
msg.T7 = state.T7;   msg.RH_7 = state.RH_7;
msg.T8 = state.T8;   msg.RH_8 = state.RH_8;
msg.T9 = state.T9;   msg.RH_9 = state.RH_9;

return msg;

// ===============================
// DELAY & THROUGHPUT CALCULATION
// ===============================

const tracing = msg.payload?.tracing || {};

const t_acq  = tracing.data_acq_send;
const t_ctrl = tracing.data_ctrl_recv;
const t_proc = tracing.data_proc_recv;

// Se il tracing non ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¾ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¾ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¨ completo, questo messaggio non ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¾ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¾ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¨ adatto al ramo delay
if (t_acq == null || t_ctrl == null || t_proc == null) {
    return null;
}

// Calcolo delay
const delay_acq_ctrl  = t_ctrl - t_acq;
const delay_ctrl_proc = t_proc - t_ctrl;
const delay_total     = t_proc - t_acq;

// Scarto valori incoerenti
if (delay_acq_ctrl < 0 || delay_ctrl_proc < 0 || delay_total < 0) {
    node.warn("Delay negativo rilevato nel tracing");
    return null;
}

// Statistiche nel context
let stats = context.get("stats");

if (!stats) {
    stats = {
        count: 0,

        min_acq_ctrl: Infinity,
        max_acq_ctrl: 0,
        sum_acq_ctrl: 0,

        min_ctrl_proc: Infinity,
        max_ctrl_proc: 0,
        sum_ctrl_proc: 0,

        min_total: Infinity,
        max_total: 0,
        sum_total: 0,

        first_time: t_proc
    };
}

stats.count++;

stats.min_acq_ctrl = Math.min(stats.min_acq_ctrl, delay_acq_ctrl);
stats.max_acq_ctrl = Math.max(stats.max_acq_ctrl, delay_acq_ctrl);
stats.sum_acq_ctrl += delay_acq_ctrl;

stats.min_ctrl_proc = Math.min(stats.min_ctrl_proc, delay_ctrl_proc);
stats.max_ctrl_proc = Math.max(stats.max_ctrl_proc, delay_ctrl_proc);
stats.sum_ctrl_proc += delay_ctrl_proc;

stats.min_total = Math.min(stats.min_total, delay_total);
stats.max_total = Math.max(stats.max_total, delay_total);
stats.sum_total += delay_total;

const elapsed = (t_proc - stats.first_time) / 1000;
const throughput = elapsed > 0 ? Math.round(stats.count / elapsed) : 0;

context.set("stats", stats);

msg.delay = {
    acq_ctrl: delay_acq_ctrl,
    ctrl_proc: delay_ctrl_proc,
    total: delay_total,

    avg_acq_ctrl: Math.round(stats.sum_acq_ctrl / stats.count),
    avg_ctrl_proc: Math.round(stats.sum_ctrl_proc / stats.count),
    avg_total: Math.round(stats.sum_total / stats.count),

    min_acq_ctrl: Math.round(stats.min_acq_ctrl),
    max_acq_ctrl: Math.round(stats.max_acq_ctrl),

    min_ctrl_proc: Math.round(stats.min_ctrl_proc),
    max_ctrl_proc: Math.round(stats.max_ctrl_proc),

    min_total: Math.round(stats.min_total),
    max_total: Math.round(stats.max_total),

    throughput: throughput
};

return msg;

// ===============================
// SAVE DELAY DATA
// ===============================

let data = flow.get("delay_export") || [];

const d = msg.delay;

// sicurezza
if (!d) return null;

// salviamo snapshot
data.push({
    timestamp: Date.now(),

    acq_ctrl: d.acq_ctrl,
    ctrl_proc: d.ctrl_proc,
    total: d.total,

    avg_total: d.avg_total,
    min_total: d.min_total,
    max_total: d.max_total,

    throughput: d.throughput
});

// evita array infinito
if (data.length > 2000) {
    data = data.slice(-2000);
}

flow.set("delay_export", data);

return msg;

// ===============================
// EXPORT DELAY CSV
// ===============================

let data = flow.get("delay_export") || [];

function formatNumber(n) {
    if (n === null || n === undefined || isNaN(n)) return '';
    return String(n).replace('.', ',');
}

let csv = "timestamp;acq_ctrl;ctrl_proc;total;avg_total;min_total;max_total;throughput\n";

for (let r of data) {
    csv += [
        r.timestamp,
        formatNumber(r.acq_ctrl),
        formatNumber(r.ctrl_proc),
        formatNumber(r.total),
        formatNumber(r.avg_total),
        formatNumber(r.min_total),
        formatNumber(r.max_total),
        formatNumber(r.throughput)
    ].join(";") + "\n";
}

msg.payload = csv;
msg.filename = "/data/delay_export.csv";

return msg;

msg.payload = msg.payload || {};
msg.payload.tracing = msg.payload.tracing || {};
msg.payload.tracing.data_proc_recv = Date.now();

return msg;

const EC = elliptic.ec;
const ec = new EC("secp256k1");

// recupera payload
let payload = msg.payload || msg;

// separa tracing e dati cifrati
const tracing = payload.tracing || null;
const encrypted = payload.encrypted || null;

if (!encrypted) {
    node.error("Sezione encrypted mancante");
    return null;
}

// chiavi ECC salvate globalmente
const keys = global.get("ecc_keys");
const keyId = encrypted.key_id;

if (!keys || !keys[keyId]) {
    node.error("Chiave privata non trovata per key_id: " + keyId);
    return null;
}

const privateKeyHex = keys[keyId];
const privateKey = ec.keyFromPrivate(privateKeyHex, "hex");

// campi cifrati
const encryptedData = encrypted.encrypted_data;
const encryptedKey = encrypted.encrypted_key;
const ivHex = encrypted.iv;
const ephemeralPubHex = encrypted.ephemeral_pub;

if (!encryptedData || !encryptedKey || !ivHex || !ephemeralPubHex) {
    node.error("Payload cifrato incompleto");
    return null;
}

const iv = Buffer.from(ivHex, "hex");

// ricostruisci chiave pubblica temporanea
const ephemeralPub = ec.keyFromPublic(ephemeralPubHex, "hex");

// ECDH
const sharedSecret = privateKey.derive(ephemeralPub.getPublic());

// derivazione chiave AES
const derivedKey = crypto
    .createHash("sha256")
    .update(sharedSecret.toString(16))
    .digest();

let decryptedAESKeyHex;

try {

    const decipherKey = crypto.createDecipheriv(
        "aes-256-cbc",
        derivedKey,
        iv
    );

    decryptedAESKeyHex = decipherKey.update(encryptedKey, "hex", "utf8");
    decryptedAESKeyHex += decipherKey.final("utf8");

} catch (err) {

    node.error("Errore decrypt AES key: " + err.message);
    return null;

}

// chiave AES finale
const aesKey = Buffer.from(decryptedAESKeyHex, "hex");

let decryptedData;

try {

    const decipher = crypto.createDecipheriv(
        "aes-256-cbc",
        aesKey,
        iv
    );

    decryptedData = decipher.update(encryptedData, "hex", "utf8");
    decryptedData += decipher.final("utf8");

} catch (err) {

    node.error("Errore decrypt payload: " + err.message);
    return null;

}

// parsing JSON
let decryptedPayload;

try {

    decryptedPayload = JSON.parse(decryptedData);

} catch (err) {

    node.error("JSON decrypt non valido");
    return null;

}

// ricostruisci payload finale mantenendo tracing
msg.payload = decryptedPayload;

if (tracing) {
    msg.payload.tracing = tracing;
}

return msg;

const t = msg.payload.tracing || {};
const metadata = msg.payload?.metadata || {};
const messageId = metadata.message_id;
const originalTopic = msg.topic;

if (!messageId) {
    node.warn("message_id mancante: tracing update scartato");
    return null;
}

msg.topic = "tracing/update";

msg.payload = {
    message_id: messageId,
    topic: originalTopic,
    data_proc_recv: t.data_proc_recv
};

return msg;

function parseTopic(topic, currentRoom, currentMetric) {
    const parts = String(topic || '').split('/');

    if (parts[0] !== 'data') {
        return {
            room: currentRoom || 'unknown',
            metric: currentMetric || 'unknown'
        };
    }

    if (parts[1] === 'home') {
        return {
            room: parts[2] || currentRoom || 'unknown',
            metric: parts[3] || currentMetric || 'unknown'
        };
    }

    return {
        room: parts[1] || currentRoom || 'unknown',
        metric: parts[2] || currentMetric || 'unknown'
    };
}

const parsed = parseTopic(msg.topic, msg.room, msg.metric);
msg.room = parsed.room;
msg.metric = parsed.metric;

msg.query = `
SELECT operator, threshold, room, metric
FROM alert_rules
WHERE room = $1
AND metric = $2
AND enabled = true;
`;

msg.params = [
    msg.room,
    msg.metric
];

return msg;

function isTriggered(operator, value, threshold) {
    switch (operator) {
        case ">":
            return value > threshold;
        case "<":
            return value < threshold;
        case ">=":
            return value >= threshold;
        case "<=":
            return value <= threshold;
        case "==":
            return value == threshold;
        case "!=":
            return value != threshold;
        default:
            return false;
    }
}

const rules = Array.isArray(msg.payload) ? msg.payload : [];
const value = Number(msg.current_value);

if (!rules.length || !Number.isFinite(value)) {
    return null;
}

const triggeredMessages = [];

for (const rule of rules) {
    const threshold = Number(rule.threshold);
    const operator = String(rule.operator || "");

    if (!Number.isFinite(threshold)) {
        continue;
    }

    if (!isTriggered(operator, value, threshold)) {
        continue;
    }

    triggeredMessages.push({
        ...msg,
        alert: true,
        payload: {
            metric: msg.metric,
            room: msg.room,
            value: value,
            threshold: threshold,
            operator: operator,
            ts: msg.ts
        }
    });
}

if (!triggeredMessages.length) {
    return null;
}

return [triggeredMessages];

let stats = global.get("metric_stats") || {};

let key = msg.room + "_" + msg.metric;

let baseline = stats[key];

if (!baseline) {
    msg.zscore = 0;
    msg.anomaly = false;
    return msg;
}

let std = baseline.stddev;

if (!std || std < 0.0001) {
    std = 0.0001;
}

let z = Math.abs(msg.current_value - baseline.mean) / std;

msg.zscore = z;
msg.anomaly = z > 3;

return msg;

let stats = global.get("metric_stats") || {};

let key = msg.room + "_" + msg.metric;

let alpha = 0.02;

if (!stats[key]) {

    stats[key] = {
        mean: msg.current_value,
        variance: 1,
        stddev: 1,
        count: 1
    };

} else {

    let s = stats[key];

    let diff = msg.current_value - s.mean;

    s.mean = s.mean + alpha * diff;

    s.variance = (1 - alpha) * (s.variance + alpha * diff * diff);

    if (s.variance < 0.0001) {
        s.variance = 0.0001;
    }

    s.stddev = Math.sqrt(s.variance);

    s.count += 1;

}

global.set("metric_stats", stats);

msg.baseline = stats[key];

return msg;

const windowSize = 30;
const metricKey = msg.analytics_key || ((msg.room || 'unknown') + '::' + (msg.metric || 'unknown'));
const value = Number(msg.current_value);

if (!Number.isFinite(value)) {
    return msg;
}

let history = context.get("correlation_history") || {};

if (!history[metricKey]) {
    history[metricKey] = [];
}

history[metricKey].push(value);

if (history[metricKey].length > windowSize) {
    history[metricKey].shift();
}

context.set("correlation_history", history);

const metrics = Object.keys(history);

function pearson(x, y) {
    if (x.length !== y.length || x.length < 5) {
        return null;
    }

    let n = x.length;
    let sumX = 0;
    let sumY = 0;
    let sumXY = 0;
    let sumX2 = 0;
    let sumY2 = 0;

    for (let i = 0; i < n; i++) {
        sumX += x[i];
        sumY += y[i];
        sumXY += x[i] * y[i];
        sumX2 += x[i] * x[i];
        sumY2 += y[i] * y[i];
    }

    let num = (n * sumXY) - (sumX * sumY);
    let den = Math.sqrt(
        (n * sumX2 - sumX * sumX) *
        (n * sumY2 - sumY * sumY)
    );

    if (den === 0) {
        return null;
    }

    return num / den;
}

let correlations = {};

for (let i = 0; i < metrics.length; i++) {
    for (let j = i + 1; j < metrics.length; j++) {
        const m1 = metrics[i];
        const m2 = metrics[j];
        correlations[`${m1}<->${m2}`] = pearson(history[m1], history[m2]);
    }
}

msg.analytics_key = metricKey;
msg.correlations = correlations;

return msg;

const metricKey = msg.analytics_key || ((msg.room || 'unknown') + '::' + (msg.metric || 'unknown'));
const value = Number(msg.current_value);
const bucket = Math.floor((Number(msg.ts) || Date.now()) / 60000);

if (!Number.isFinite(value)) {
    return msg;
}

let seasonData = context.get("seasonality_data") || {};

if (!seasonData[metricKey]) {
    seasonData[metricKey] = {};
}

let metricSeason = seasonData[metricKey];
metricSeason[bucket] = value;

let keys = Object.keys(metricSeason)
    .map(Number)
    .sort((a, b) => a - b);

while (keys.length > 60) {
    const oldest = keys.shift();
    delete metricSeason[oldest];
}

seasonData[metricKey] = metricSeason;
context.set("seasonality_data", seasonData);

const values = Object.values(metricSeason);

if (values.length < 10) {
    msg.analytics_key = metricKey;
    msg.seasonality = false;
    msg.seasonality_strength = 0;
    return msg;
}

const avg = values.reduce((a, b) => a + b, 0) / values.length;
const variance = values.reduce((a, b) => a + Math.pow(b - avg, 2), 0) / values.length;

msg.analytics_key = metricKey;
msg.seasonality_strength = variance;
msg.seasonality = variance > 5;

return msg;

// ===============================
// ANALYTICS ENGINE
// ===============================

const metricKey = msg.analytics_key || ((msg.room || 'unknown') + '::' + (msg.metric || 'unknown'));
const value = Number(msg.current_value);

if (!Number.isFinite(value)) {
    return null;
}

const windowSize = 20;
let history = context.get("analytics_history") || {};

if (!history[metricKey]) {
    history[metricKey] = [];
}

history[metricKey].push(value);

if (history[metricKey].length > windowSize) {
    history[metricKey].shift();
}

context.set("analytics_history", history);

const values = history[metricKey];
const avg = values.reduce((a, b) => a + b, 0) / values.length;
const variance = values.reduce((a, b) => a + Math.pow(b - avg, 2), 0) / values.length;
const prev = values.length >= 2 ? values[values.length - 2] : value;

msg.analytics_key = metricKey;
msg.moving_avg = avg;
msg.instability_score = Math.sqrt(variance);

if (value > prev) {
    msg.trend = "up";
} else if (value < prev) {
    msg.trend = "down";
} else {
    msg.trend = "stable";
}

msg.spike = Math.abs(value - avg) > Math.max(Math.abs(avg) * 0.2, 0.5);

return msg;

let p = msg.payload;

let metricName = msg.topic || "unknown";

// prendi solo l'ultima parte del topic
if (metricName.includes("/")) {
