const alert = msg.payload || {};
const room = String(alert.room || 'unknown');
const metric = String(alert.metric || 'metric');
const operator = String(alert.operator || '?');
const threshold = Number(alert.threshold);
const value = Number(alert.value);
const now = Date.now();
const cooldowns = context.get('alert_cooldowns') || {};
const cooldownMs = 60000;
const alertKey = room + ':' + metric + ':' + operator + ':' + threshold;

if (!Number.isFinite(value)) {
