function toTimestamp(input) {
    const parsed = Date.parse(input);
    return Number.isFinite(parsed) ? parsed : Date.now();
}

let state = context.get('energy_state') || {
    latest: {
        appliances: null,
        lights: null
    },
    pending: {
        key: '',
        appliances: null,
        lights: null
    },
    history: []
};

const sampleKey = metadata.original_date || String(Date.now());
const sampleTs = toTimestamp(metadata.original_date);

state.latest[metric] = value;

if (state.pending.key !== sampleKey) {
    state.pending = {
        key: sampleKey,
        appliances: null,
        lights: null,
        timestamp: sampleTs,
        original_date: metadata.original_date || sampleKey
    };
}

state.pending[metric] = value;

if (state.latest.appliances === null || state.latest.lights === null) {
    context.set('energy_state', state);
    return null;
}

const committed = state.pending.appliances !== null && state.pending.lights !== null;

if (committed) {
    const snapshot = {
        key: state.pending.key,
        timestamp: state.pending.timestamp,
        original_date: state.pending.original_date,
        appliances: state.pending.appliances,
        lights: state.pending.lights,
        total: state.pending.appliances + state.pending.lights
    };

    const lastKey = state.history.length ? state.history[state.history.length - 1].key : null;
    if (lastKey !== snapshot.key) {
        state.history.push(snapshot);
    }

    if (state.history.length > 96) {
        state.history = state.history.slice(-96);
    }

    state.latest.appliances = snapshot.appliances;
    state.latest.lights = snapshot.lights;
}

const totalLoad = state.latest.appliances + state.latest.lights;
let series = state.history.slice();

if (!series.length || series[series.length - 1].key !== sampleKey) {
    series = series.concat([{
        key: sampleKey,
        timestamp: sampleTs,
        original_date: metadata.original_date || sampleKey,
        appliances: state.latest.appliances,
        lights: state.latest.lights,
        total: totalLoad
    }]);
}

const rolling = series.slice(-24);
const totals = rolling.map((entry) => entry.total);
const avgTotal = totals.reduce((sum, current) => sum + current, 0) / totals.length;
const peakTotal = Math.max(...totals);
const baselineGap = totalLoad - avgTotal;
const estimatedDailyKwh = (avgTotal * 24) / 1000;
const lightsShare = totalLoad > 0 ? (state.latest.lights / totalLoad) * 100 : 0;

const indoorState = global.get('indoor_temperature_state') || {};
const roomEntries = Object.entries(indoorState.rooms || {});
const indoorTemps = roomEntries
    .filter(([room, entry]) => room !== 'outside_building' && Number.isFinite(Number(entry?.value)))
    .map(([, entry]) => Number(entry.value));
const outsideTempEntry = indoorState.rooms?.outside_building;
const outsideTemp = Number(outsideTempEntry?.value);
const avgIndoorTemp = indoorTemps.length
    ? indoorTemps.reduce((sum, current) => sum + current, 0) / indoorTemps.length
    : null;
const deltaTemperature = Number.isFinite(avgIndoorTemp) && Number.isFinite(outsideTemp)
    ? avgIndoorTemp - outsideTemp
    : null;
const efficiencyValue = Number.isFinite(deltaTemperature) && Math.abs(deltaTemperature) > 0.1
    ? totalLoad / deltaTemperature
    : null;

let loadState = 'Low load';
if (totalLoad >= 450) {
    loadState = 'High load';
} else if (totalLoad >= 180) {
    loadState = 'Moderate load';
}

let recommendation = 'Consumption profile is stable.';
if (lightsShare > 35 && state.latest.lights > 20) {
    recommendation = 'Lighting is taking an unusually large share of the load.';
} else if (baselineGap > 80 && rolling.length >= 6) {
    recommendation = 'Current load is well above the rolling baseline.';
} else if (baselineGap < -80 && rolling.length >= 6) {
    recommendation = 'Current load is below the recent baseline.';
}

let efficiencyText = 'Waiting for indoor/outdoor temperatures';
if (efficiencyValue !== null) {
    efficiencyText = efficiencyValue.toFixed(2) + ' W/°C';
}

if (efficiencyValue !== null && Number.isFinite(avgIndoorTemp) && Number.isFinite(outsideTemp)) {
    efficiencyText += ' (Tin ' + avgIndoorTemp.toFixed(1) + ' °C, Tout ' + outsideTemp.toFixed(1) + ' °C)';
}

const currentSnapshot = series[series.length - 1];
const summary = {
    original_date: currentSnapshot.original_date,
    appliances: Number(state.latest.appliances.toFixed(1)),
    lights: Number(state.latest.lights.toFixed(1)),
    total_load: Number(totalLoad.toFixed(1)),
    avg_total_text: avgTotal.toFixed(1) + ' W',
    peak_total_text: peakTotal.toFixed(1) + ' W',
    daily_energy_text: estimatedDailyKwh.toFixed(2) + ' kWh/day',
    lights_share_text: lightsShare.toFixed(1) + '%',
    baseline_gap_text: (baselineGap >= 0 ? '+' : '') + baselineGap.toFixed(1) + ' W',
    load_state: loadState,
    recommendation: recommendation,
    efficiency_text: efficiencyText,
    avg_indoor_temp: Number.isFinite(avgIndoorTemp) ? Number(avgIndoorTemp.toFixed(1)) : null,
    outside_temp: Number.isFinite(outsideTemp) ? Number(outsideTemp.toFixed(1)) : null,
    temperature_delta: Number.isFinite(deltaTemperature) ? Number(deltaTemperature.toFixed(1)) : null,
    efficiency_value: efficiencyValue !== null ? Number(efficiencyValue.toFixed(2)) : null,
    timestamp: currentSnapshot.timestamp
};

context.set('energy_state', state);

return [
    summary,
    {
        topic: 'Total load',
        payload: summary.total_load,
        timestamp: currentSnapshot.timestamp
    },
    {
        topic: 'Appliances',
        payload: summary.appliances,
        timestamp: currentSnapshot.timestamp
    },
    {
        topic: 'Lights',
        payload: summary.lights,
        timestamp: currentSnapshot.timestamp
    }
];

// recupera array
let data = flow.get("energy_export") || [];

// salva solo quello che ti serve
data.push({
    timestamp: msg.timestamp,
    date: msg.original_date,
    appliances: msg.appliances,
    lights: msg.lights,
    total: msg.total_load,
    efficiency: msg.efficiency_value
});

// evita array infinito (opzionale)
if (data.length > 1000) {
    data = data.slice(-1000);
}

// salva
flow.set("energy_export", data);

return msg;

// ===============================
// EXPORT CSV - VERSIONE PULITA
// ===============================

let data = flow.get("energy_export") || [];

function formatNumber(n) {
    if (n === null || n === undefined || isNaN(n)) return '';
    return Number(n).toFixed(2).replace('.', ',');
}

// HEADER (prima riga vera)
let csv = "timestamp;date;appliances;lights;total;efficiency\n";

// DATI
for (let r of data) {
    csv += [
        r.timestamp || '',
        r.date || '',
        formatNumber(r.appliances),
        formatNumber(r.lights),
        formatNumber(r.total),
        formatNumber(r.efficiency)
    ].join(";") + "\n";
}

// OUTPUT
msg.payload = csv;
msg.filename = "/data/energy_export.csv";

return msg;
